class _RestoreWalletViewState extends ConsumerState<RestoreWalletView> {
  final _formKey = GlobalKey<FormState>();
  late final int _seedWordCount;
  late final bool isDesktop;

  final HashSet<String> _wordListHashSet = HashSet.from(bip39wordlist.WORDLIST);
  final ScrollController controller = ScrollController();

  final List<TextEditingController> _controllers = [];
  final List<FormInputStatus> _inputStatuses = [];

  /// Focus of the word fields (mobile), to suggest words for the one
  /// being typed and move on to the next.
  final List<FocusNode> _focusNodes = [];

  /// The word field being typed in, or null.
  int? _focusedField;

  late final TextSelectionControls textSelectionControls;

  bool _hideSeedWords = false;

  Future<void> onControlsPaste(TextSelectionDelegate delegate) async {
    final data = await widget.clipboard.getData(Clipboard.kTextPlain);
    if (data?.text == null) {
      return;
    }

    final text = data!.text!.trim();
    if (text.isEmpty || _controllers.isEmpty) {
      unawaited(delegate.pasteText(SelectionChangedCause.toolbar));
      return;
    }

    final words = _mnemonicWords(text);
    if (words.isEmpty) {
      unawaited(delegate.pasteText(SelectionChangedCause.toolbar));
      return;
    }

    if (words.length == 1) {
      _controllers.first.text = words.first;
      if (_isValidMnemonicWord(words.first.toLowerCase())) {
        setState(() {
          _inputStatuses.first = FormInputStatus.valid;
        });
      } else {
        setState(() {
          _inputStatuses.first = FormInputStatus.invalid;
        });
      }
      return;
    }

    _clearAndPopulateMnemonic(words);
  }

  @override
  void initState() {
    _seedWordCount = widget.seedWordsLength;
    isDesktop = Util.isDesktop;

    textSelectionControls = Platform.isIOS
        ? CustomCupertinoTextSelectionControls(onPaste: onControlsPaste)
        : CustomMaterialTextSelectionControls(onPaste: onControlsPaste);

    for (int i = 0; i < _seedWordCount; i++) {
      _controllers.add(TextEditingController());
      _inputStatuses.add(FormInputStatus.empty);
      final index = i;
      _focusNodes.add(
        FocusNode()..addListener(() {
          if (!mounted) return;
          final focused = _focusNodes[index].hasFocus;
          if (focused != (_focusedField == index)) {
            setState(() => _focusedField = focused ? index : null);
          }
        }),
      );
    }

    super.initState();
  }

  @override
  void dispose() {
    for (final element in _controllers) {
      element.dispose();
    }
    for (final node in _focusNodes) {
      node.dispose();
    }

    super.dispose();
  }

  bool _isValidMnemonicWord(String word) => _wordListHashSet.contains(word);

  /// Up to 4 words of the list starting with what field [index] holds;
  /// none when it holds a whole word nothing longer starts with.
  List<String> _suggestionsFor(int index) {
    final prefix = _controllers[index].text.trim().toLowerCase();
    if (prefix.isEmpty) return const [];
    final words = bip39wordlist.WORDLIST
        .where((w) => w.startsWith(prefix))
        .take(4)
        .toList();
    return words.length == 1 && words.first == prefix ? const [] : words;
  }

  /// Put a suggested [word] in field [index] and go on to the next one.
  void _pickSuggestion(int index, String word) {
    _controllers[index].value = TextEditingValue(
      text: word,
      selection: TextSelection.collapsed(offset: word.length),
    );
    setState(() => _inputStatuses[index] = FormInputStatus.valid);
    if (index + 1 < _focusNodes.length) {
      _focusNodes[index + 1].requestFocus();
    } else {
      _focusNodes[index].unfocus();
    }
  }

  /// Next / Done on the keyboard: a partly typed word becomes its first
  /// suggestion; then on to the next field.
  void _submitWord(int index) {
    final typed = _controllers[index].text.trim().toLowerCase();
    final suggestions = _suggestionsFor(index);
    if (!_isValidMnemonicWord(typed) && suggestions.isNotEmpty) {
      _pickSuggestion(index, suggestions.first);
    } else if (index + 1 < _focusNodes.length) {
      _focusNodes[index + 1].requestFocus();
    }
  }

  Widget _wordSuggestions(int index) {
    final words = _hideSeedWords ? const <String>[] : _suggestionsFor(index);
    if (words.isEmpty) return const SizedBox.shrink();
    final colors = Theme.of(context).extension<StackColors>()!;
    return Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Align(
        alignment: Alignment.centerLeft,
        child: Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            // The first one stands out: Next takes it.
            for (final (n, word) in words.indexed)
              ActionChip(
                label: Text(
                  word,
                  style: STextStyles.field(context).copyWith(
                    color: colors.textRestore,
                    fontSize: 14,
                    fontWeight: n == 0 ? FontWeight.w600 : null,
                  ),
                ),
                backgroundColor: colors.textFieldDefaultBG,
                side: BorderSide(
                  color: n == 0
                      ? colors.accentColorBlue
                      : colors.textFieldActiveBG,
                ),
                onPressed: () => _pickSuggestion(index, word),
              ),
          ],
        ),
      ),
    );
  }

  OutlineInputBorder _buildOutlineInputBorder(Color color) {
    return OutlineInputBorder(
      borderSide: BorderSide(width: 1, color: color),
      borderRadius: BorderRadius.circular(Constants.size.circularBorderRadius),
    );
  }

  Future<void> attemptRestore() async {
    if (_formKey.currentState!.validate()) {
      if (mounted) setState(() => _hideSeedWords = true);

      String mnemonic = "";
      for (final element in _controllers) {
        mnemonic += " ${element.text.trim().toLowerCase()}";
      }
      mnemonic = mnemonic.trim();

      if (bip39.validateMnemonic(mnemonic) == false) {
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.warning,
            message: "Invalid seed phrase!",
            context: context,
          ),
        );
      } else {
        if (!Platform.isLinux) await WakelockPlus.enable();

        final info = WalletInfo.createNew(
          coin: widget.coin,
          name: widget.walletName,
          restoreHeight: widget.restoreBlockHeight,
        );

        bool isRestoring = true;
        // show restoring in progress

        if (mounted) {
          unawaited(
            showDialog<dynamic>(
              context: context,
              useSafeArea: false,
              barrierDismissible: false,
              builder: (context) {
                return RestoringDialog(
                  walletId: info.walletId,
                  onCancel: () async {
                    isRestoring = false;

                    if (mounted) setState(() => _hideSeedWords = false);

                    await ref
                        .read(pWallets)
                        .deleteWallet(info, ref.read(secureStoreProvider));
                  },
                );
              },
            ),
          );
        }

        var node = ref
            .read(nodeServiceChangeNotifierProvider)
            .getPrimaryNodeFor(currency: widget.coin);

        if (node == null) {
          node = widget.coin.defaultNode(isPrimary: true);
          await ref
              .read(nodeServiceChangeNotifierProvider)
              .save(node, null, false);
        }

        try {
          final wallet = await Wallet.create(
            walletInfo: info,
            mainDB: ref.read(mainDBProvider),
            secureStorageInterface: ref.read(secureStoreProvider),
            nodeService: ref.read(nodeServiceChangeNotifierProvider),
            prefs: ref.read(prefsChangeNotifierProvider),
            mnemonicPassphrase: widget.mnemonicPassphrase,
            mnemonic: mnemonic,
          );

          await wallet.init();
          await wallet.recover(isRescan: false);

          if (wallet is ExternalWallet) {
            await wallet.exit();
          }

          // check if state is still active before continuing
          if (mounted) {
            await wallet.info.setMnemonicVerified(
              isar: ref.read(mainDBProvider).isar,
            );

            if (ref.read(pDuress)) {
              await wallet.info.updateDuressVisibilityStatus(
                isDuressVisible: true,
                isar: ref.read(mainDBProvider).isar,
              );
            }

            ref.read(pWallets).addWallet(wallet);

            if (mounted) {
              if (isDesktop) {
                Navigator.of(context)
                    .popUntil(ModalRoute.withName(DesktopHomeView.routeName));
              } else {
                unawaited(
                  Navigator.of(context).pushNamedAndRemoveUntil(
                    HomeView.routeName,
                    (route) => false,
                  ),
                );
              }

              await showDialog<dynamic>(
                context: context,
                useSafeArea: false,
                barrierDismissible: true,
                builder: (context) {
                  return const RestoreSucceededDialog();
                },
              );
            }

            if (!Platform.isLinux && !isDesktop) {
              await WakelockPlus.disable();
            }
          }
        } catch (e) {
          if (!Platform.isLinux && !isDesktop) {
            await WakelockPlus.disable();
          }

          // if (e is HiveError &&
          //     e.message == "Box has already been closed.") {
          //   // restore was cancelled
          //   return;
          // }

          // check if state is still active and restore wasn't cancelled
          // before continuing
          if (mounted && isRestoring) {
            // pop waiting dialog
            Navigator.pop(context);

            // show restoring wallet failed dialog
            await showDialog<dynamic>(
              context: context,
              useSafeArea: false,
              barrierDismissible: true,
              builder: (context) {
                return RestoreFailedDialog(
                  errorMessage: e.toString(),
                  walletId: info.walletId,
                  walletName: info.name,
                );
              },
            );

            if (mounted) setState(() => _hideSeedWords = false);
          }
        }

        if (!Platform.isLinux && !isDesktop) {
          await WakelockPlus.disable();
        }
      }
    }
  }

  InputDecoration _getInputDecorationFor(
    FormInputStatus status,
    String prefix,
  ) {
    Color color;
    Color prefixColor;
    Color borderColor;
    Widget? suffixIcon;
    switch (status) {
      case FormInputStatus.empty:
        color = Theme.of(context).extension<StackColors>()!.textFieldDefaultBG;
        prefixColor = Theme.of(context).extension<StackColors>()!.textSubtitle2;
        borderColor = Theme.of(context)
            .extension<StackColors>()!
            .textFieldDefaultBG;
        break;
      case FormInputStatus.invalid:
        color = Theme.of(context).extension<StackColors>()!.textFieldErrorBG;
        prefixColor = Theme.of(context)
            .extension<StackColors>()!
            .textFieldErrorSearchIconLeft;
        borderColor = Theme.of(context)
            .extension<StackColors>()!
            .textFieldErrorBorder;
        suffixIcon = SvgPicture.asset(
          Assets.svg.alertCircle,
          width: 16,
          height: 16,
          color: Theme.of(context)
              .extension<StackColors>()!
              .textFieldErrorSearchIconRight,
        );
        break;
      case FormInputStatus.valid:
        color = Theme.of(context).extension<StackColors>()!.textFieldSuccessBG;
        prefixColor = Theme.of(context)
            .extension<StackColors>()!
            .textFieldSuccessSearchIconLeft;
        borderColor = Theme.of(context)
            .extension<StackColors>()!
            .textFieldSuccessBorder;
        suffixIcon = SvgPicture.asset(
          Assets.svg.checkCircle,
          width: 16,
          height: 16,
          color: Theme.of(context)
              .extension<StackColors>()!
              .textFieldSuccessSearchIconRight,
        );
        break;
    }
    return InputDecoration(
      fillColor: color,
      filled: true,
      contentPadding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),
      prefixIcon: Align(
        alignment: Alignment.centerLeft,
        child: Padding(
          padding: const EdgeInsets.only(left: 12, bottom: 2),
          child: Text(
            prefix,
            style: STextStyles.fieldLabel(
              context,
            ).copyWith(color: prefixColor, fontSize: Util.isDesktop ? 16 : 14),
          ),
        ),
      ),
      prefixIconConstraints: const BoxConstraints(
        minWidth: 16,
        minHeight: 16,
        maxWidth: 36,
        maxHeight: 32,
      ),
      suffixIconConstraints: const BoxConstraints(
        minWidth: 16,
        minHeight: 16,
        maxWidth: 28,
        maxHeight: 16,
      ),
      suffixIcon: Center(
        child: Padding(
          padding: const EdgeInsets.only(right: 12),
          child: suffixIcon,
        ),
      ),
      enabledBorder: _buildOutlineInputBorder(borderColor),
      focusedBorder: _buildOutlineInputBorder(borderColor),
      errorBorder: _buildOutlineInputBorder(borderColor),
      disabledBorder: _buildOutlineInputBorder(borderColor),
      focusedErrorBorder: _buildOutlineInputBorder(borderColor),
    );
  }

  /// Words of a pasted phrase: split on any whitespace (spaces, new
  /// lines), without the numbers of a numbered list ("1. word").
  static List<String> _mnemonicWords(String text) => text
      .trim()
      .split(RegExp(r"\s+"))
      .where((w) => w.isNotEmpty && !RegExp(r"^\d+[.):]?$").hasMatch(w))
      .toList();

  /// A whole phrase pasted (or typed by a keyboard's clipboard) into the
  /// field at [index]: spread its words over the fields. Pasted into the
  /// first field, or as many words as the phrase has, it fills them all;
  /// otherwise the fields from [index] on. Returns whether it did.
  bool _spreadPastedWords(String value, int index) {
    final words = _mnemonicWords(value);
    if (words.length < 2) return false;
    if (index == 0 || words.length >= _controllers.length) {
      _clearAndPopulateMnemonic(words);
    } else {
      _populateMnemonicFrom(index, words);
    }
    return true;
  }

  void _populateMnemonicFrom(int start, List<String> words) {
    final end = min(_controllers.length, start + words.length);
    setState(() {
      for (int i = start; i < end; i++) {
        final word = words[i - start];
        _controllers[i].text = word;
        _inputStatuses[i] = _isValidMnemonicWord(word.toLowerCase())
            ? FormInputStatus.valid
            : FormInputStatus.invalid;
      }
    });
  }

  void _clearAndPopulateMnemonic(List<String> words) {
    final count = min(_controllers.length, words.length);

    // replace field content with listed words
    for (int i = 0; i < count; i++) {
      final word = words[i].trim();
      _controllers[i].text = word;
      if (_isValidMnemonicWord(word.toLowerCase())) {
        setState(() {
          _inputStatuses[i] = FormInputStatus.valid;
        });
      } else {
        setState(() {
          _inputStatuses[i] = FormInputStatus.invalid;
        });
      }
    }

    // clear remaining fields
    for (int i = count; i < _controllers.length; i++) {
      _controllers[i].text = "";
      setState(() {
        _inputStatuses[i] = FormInputStatus.empty;
      });
    }

    if (!isDesktop) {
      controller.animateTo(
        controller.position.maxScrollExtent,
        duration: const Duration(milliseconds: 300),
        curve: Curves.decelerate,
      );
    }
  }

  Future<void> scanMnemonicQr() async {
    try {
      final qrResult = await ref.read(pBarcodeScanner).scan(context: context);

      final results = AddressUtils.decodeQRSeedData(qrResult.rawContent ?? "");

      if (results["mnemonic"] != null) {
        final list = (results["mnemonic"] as List)
            .map((value) => value as String)
            .toList(growable: false);
        if (list.isNotEmpty) {
          _clearAndPopulateMnemonic(list);
          Logging.instance.i("mnemonic populated");
        } else {
          Logging.instance.i("mnemonic failed to populate");
        }
      }
    } on PlatformException catch (e, s) {
      // likely failed to get camera permissions
      if (mounted) {
        try {
          await checkCamPermDeniedMobileAndOpenAppSettings(
            context,
            logging: Logging.instance,
          );
        } catch (e, s) {
          Logging.instance.e(
            "Failed to check cam permissions",
            error: e,
            stackTrace: s,
          );
        }
      } else {
        Logging.instance.e(
          "Restore wallet qr scan failed: $e",
          error: e,
          stackTrace: s,
        );
      }
    }
  }

  Future<void> pasteMnemonic() async {
    //todo: check if print needed
    // debugPrint("restoreWalletPasteButton tapped");
    final ClipboardData? data = await widget.clipboard.getData(
      Clipboard.kTextPlain,
    );

    if (data?.text != null && data!.text!.isNotEmpty) {
      _clearAndPopulateMnemonic(_mnemonicWords(data.text!));
    }
  }

  Future<void> requestRestore() async {
    // wait for keyboard to disappear
    FocusScope.of(context).unfocus();
    await Future<void>.delayed(const Duration(milliseconds: 100));

    if (mounted) {
      await showDialog<dynamic>(
        context: context,
        useSafeArea: false,
        barrierDismissible: true,
        builder: (context) {
          return ConfirmRecoveryDialog(onConfirm: attemptRestore);
        },
      );
    }
  }

